  const stopLiveCamera = () => {
    if (mediaStreamRef.current) {
      mediaStreamRef.current.getTracks().forEach((track) => track.stop());
      mediaStreamRef.current = null;
    }
    setIsLiveCameraActive(false);
  };
  const startLiveCamera = async (facing = cameraFacing) => {
    setCameraError(null);
    stopLiveCamera();
    try {
      if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
        throw new Error("Tu navegador o dispositivo no soporta acceso directo a cámara.");
      }
      const constraints = {
        video: {
          facingMode: facing,
          width: { ideal: 1280 },
          height: { ideal: 720 }
        },
        audio: false
      };
      const stream = await navigator.mediaDevices.getUserMedia(constraints);
      mediaStreamRef.current = stream;
      setIsLiveCameraActive(true);
      setCameraFacing(facing);
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        videoRef.current.play().catch(() => {});
      }
    } catch (err) {
      console.warn("No se pudo acceder a la cámara web:", err);
      setCameraError(err.name === "NotAllowedError" || err.name === "PermissionDeniedError" ? "Permiso denegado. Puedes habilitar la cámara en el candado del navegador o subir una foto desde tu galería." : "No se pudo iniciar la cámara web. Puedes subir una foto de tu archivo o usar las muestras de campo.");
      setIsLiveCameraActive(false);
    }
  };
