// src/core/sync/SyncEngine.ts
class SyncEngine {
  static listeners = new Set;
  static isSyncing = false;
  static subscribe(listener) {
    this.listeners.add(listener);
    this.notifyStatus();
    return () => this.listeners.delete(listener);
  }
  static async notifyStatus(lastSyncTimestamp) {
    const pending = await getPendingOfflineLots();
    this.listeners.forEach((listener) => {
      listener({
        isSyncing: this.isSyncing,
        pendingCount: pending.length,
        lastSyncTimestamp
      });
    });
  }
  static async enqueueHarvestLot(lot) {
    await saveOfflineLot(lot);
    await this.notifyStatus();
  }
  static async processQueue() {
    if (this.isSyncing) {
      return { syncedCount: 0, failedCount: 0, syncedIds: [] };
    }
    if (typeof navigator !== "undefined" && !navigator.onLine) {
      console.log("SyncEngine: Sin conexión a internet. La sincronización se pospone.");
      return { syncedCount: 0, failedCount: 0, syncedIds: [] };
    }
    this.isSyncing = true;
    await this.notifyStatus();
    const pending = await getPendingOfflineLots();
    const syncedIds = [];
    let failedCount = 0;
    for (const lot of pending) {
      try {
        const digest = await CryptoEngine.generateCommunityDigest({
          producerName: lot.producerName,
          community: lot.community,
          timestamp: lot.recordedAt,
          photoBase64: lot.photoDataUrl
        });
        console.log(`SyncEngine: Sellando lote ${lot.tempId} con hash ${digest.slice(0, 16)}...`);
        await new Promise((r) => setTimeout(r, 300));
        await removeOfflineLot(lot.tempId);
        syncedIds.push(lot.tempId);
      } catch (err) {
        console.error(`SyncEngine: Error al sincronizar lote ${lot.tempId}:`, err);
        failedCount++;
      }
    }
    this.isSyncing = false;
    const now = Date.now();
    await this.notifyStatus(now);
    return {
      syncedCount: syncedIds.length,
      failedCount,
      syncedIds
    };
  }
  static initAutoSync() {
    if (typeof window === "undefined")
      return;
    window.addEventListener("online", () => {
      console.log("SyncEngine: Conexión recuperada. Procesando cola de cosechas pendientes...");
      this.processQueue();
    });
  }
}
// src/core/policy/FairTradeEngine.ts
var CROP_POLICIES = {
  cafe: {
    minimumPricePerKgMxn: 90,
    recommendedPricePerKgMxn: 135,
    antiCoyoteAlertThreshold: 65
  },
  miel: {
    minimumPricePerKgMxn: 120,
    recommendedPricePerKgMxn: 180,
    antiCoyoteAlertThreshold: 80
  },
  pulque: {
    minimumPricePerKgMxn: 35,
    recommendedPricePerKgMxn: 55,
    antiCoyoteAlertThreshold: 25
  },
  artesania: {
    minimumPricePerKgMxn: 250,
    recommendedPricePerKgMxn: 450,
    antiCoyoteAlertThreshold: 180
  }
};

class FairTradeEngine {
  static evaluatePrice(cropType, price) {
    const policy = CROP_POLICIES[cropType] || CROP_POLICIES.cafe;
    if (price < policy.antiCoyoteAlertThreshold) {
      return {
        isFair: false,
        isAntiCoyoteWarning: true,
        message: `⚠️ Alerta de Coyotaje: El precio ($${price} MXN) está muy por debajo del costo de producción regional ($${policy.minimumPricePerKgMxn} MXN).`
      };
    }
    if (price < policy.minimumPricePerKgMxn) {
      return {
        isFair: false,
        isAntiCoyoteWarning: false,
        message: `El precio está por debajo del mínimo sugerido de la cooperativa ($${policy.minimumPricePerKgMxn} MXN).`
      };
    }
    return {
      isFair: true,
      isAntiCoyoteWarning: false,
      message: `✅ Precio de comercio justo verificado ($${price} MXN).`
    };
  }
  static calculateSecondaryRoyalty(salePriceMxn, royaltyPercentage = 8) {
    const artisanRoyaltyMxn = Math.round(salePriceMxn * royaltyPercentage / 100);
    const cooperativeFundMxn = Math.round(salePriceMxn * 2 / 100);
    const sellerNetMxn = salePriceMxn - artisanRoyaltyMxn - cooperativeFundMxn;
    return {
      artisanRoyaltyMxn,
      cooperativeFundMxn,
      sellerNetMxn
    };
  }
}
